import React from 'react';
import PropTypes from 'prop-types';
import { useSelector } from 'react-redux';
import {
  AvatarAccountSize,
  Box,
  BoxAlignItems,
  BoxJustifyContent,
} from '@metamask/design-system-react';
import {
  AvatarNetwork,
  AvatarNetworkSize,
  AvatarTokenSize,
  Text,
} from '../../component-library';
import {
  BlockSize,
  Display,
  TextAlign,
  TextColor,
  TextVariant,
} from '../../../helpers/constants/design-system';
import Tooltip from '../../ui/tooltip';
import { AvatarGroup } from '../../multichain/avatar-group';
import { AvatarType } from '../../multichain/avatar-group/avatar-group.types';
import { useI18nContext } from '../../../hooks/useI18nContext';
import { formatDate } from '../../../helpers/utils/util';
import { CHAIN_ID_TO_NETWORK_IMAGE_URL_MAP } from '../../../../shared/constants/network';
import {
  getAvatarType,
  PreferredAvatar,
} from '../preferred-avatar/preferred-avatar';

/**
 * Renders status of the given permission. Used by PermissionCell component.
 *
 * @param props - The props.
 * @param props.revoked - Boolean value to identify if permission is being revoked.
 * @param props.dateApproved - Timestamp when permission is approved.
 * @param props.accounts - List of accounts for which permission is requested, approved or revoked.
 * @param props.approved - Boolean value in case a permission has been approved, but there is no date to show.
 * @param props.networks
 * @returns React element rendering permission status with or without account icons displayed as AvatarGroup.
 */
export const PermissionCellStatus = ({
  revoked,
  approved,
  dateApproved,
  accounts,
  networks,
}) => {
  const t = useI18nContext();
  const avatarAccountVariant = useSelector(getAvatarType);

  const renderAccountsGroup = () => (
    <>
      {networks.length > 0 ? (
        <Box
          asChild
          className="permission-cell__status__accounts-group-box inline-flex"
        >
          <span>
            <Box className="flex flex-col">
              {networks?.map((network, index) => {
                // Get network icon: try EVM chain ID map first, then rpcPrefs.imageUrl for non-EVM
                const networkImageUrl =
                  CHAIN_ID_TO_NETWORK_IMAGE_URL_MAP[network.chainId] ??
                  network.rpcPrefs?.imageUrl ??
                  network.nativeTokenIconUrl;
                return (
                  <Box
                    key={`${network.name}_${index}`}
                    className="flex"
                    justifyContent={BoxJustifyContent.Start}
                    alignItems={BoxAlignItems.Center}
                    marginTop={2}
                  >
                    <AvatarNetwork
                      size={AvatarNetworkSize.Xs}
                      src={networkImageUrl}
                      name={network.name}
                    />
                    <Text variant={TextVariant.bodyMdMedium} marginLeft={2}>
                      {network.name}
                    </Text>
                  </Box>
                );
              })}
            </Box>
          </span>
        </Box>
      ) : (
        <Box
          asChild
          className="permission-cell__status__accounts-group-box inline-flex"
        >
          <span>
            <Tooltip
              position="bottom"
              html={
                <Box
                  className="flex flex-col"
                  justifyContent={BoxJustifyContent.Center}
                  alignItems={BoxAlignItems.Center}
                >
                  <Text
                    variant={TextVariant.headingSm}
                    color={TextColor.textAlternative}
                    textAlign={TextAlign.Center}
                  >
                    {t('accounts')}
                  </Text>
                  <Box className="flex flex-col">
                    {accounts.map((account, index) => (
                      <Box
                        key={`${account.avatarValue}_${index}`}
                        className="flex"
                        justifyContent={BoxJustifyContent.Start}
                        alignItems={BoxAlignItems.Center}
                        marginTop={2}
                      >
                        <PreferredAvatar
                          address={account.avatarValue}
                          size={AvatarAccountSize.Xs}
                        />
                        <Text variant={TextVariant.bodyMdMedium} marginLeft={2}>
                          {account.avatarName}
                        </Text>
                      </Box>
                    ))}
                  </Box>
                </Box>
              }
            >
              <AvatarGroup
                limit={3}
                members={accounts}
                avatarType={AvatarType.ACCOUNT}
                variant={avatarAccountVariant}
                size={AvatarTokenSize.Xs}
                width={BlockSize.Min}
                marginLeft={4}
                paddingLeft={4}
              />
            </Tooltip>
          </span>
        </Box>
      )}
    </>
  );

  // Check if we have content to display (either accounts or networks).
  // This is important for switch ethereum chain requests where we only have networks
  // to display (no accounts), but still need to call renderAccountsGroup() to show
  // the network cells. The renderAccountsGroup function internally decides whether
  // to render networks (when networks.length > 0) or accounts.
  const hasAccountsOrNetworks =
    (accounts && accounts.length > 0) || (networks && networks.length > 0);

  const getStatusMessage = () => {
    if (revoked) {
      return hasAccountsOrNetworks
        ? t('permissionRevokedForAccounts', [renderAccountsGroup()])
        : t('permissionRevoked');
    }

    if (dateApproved) {
      return hasAccountsOrNetworks
        ? t('approvedOnForAccounts', [
            formatDate(dateApproved, 'yyyy-MM-dd'),
            renderAccountsGroup(),
          ])
        : t('approvedOn', [formatDate(dateApproved, 'yyyy-MM-dd')]);
    }

    if (approved) {
      return t('approved');
    }

    return hasAccountsOrNetworks
      ? t('permissionRequestedForAccounts', [renderAccountsGroup()])
      : t('permissionRequested');
  };

  return (
    <Text
      as="div"
      className="permission-cell__status"
      variant={TextVariant.bodySm}
      color={TextColor.textAlternative}
      display={Display.Flex}
    >
      {getStatusMessage()}
    </Text>
  );
};

PermissionCellStatus.propTypes = {
  revoked: PropTypes.bool,
  approved: PropTypes.bool,
  dateApproved: PropTypes.number,
  accounts: PropTypes.array,
  networks: PropTypes.array,
};
